"""Implementation of actions for the Logout UI in the Mosaiq application"""
import time

from .objects.mosaiq_core_objects import MosaiqCoreObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_logout_button() -> None:
    """Locates the Logout Button on the main dashboard > clicks located object using the primary mouse button.
    """
    CommonActions.left_click_object(MosaiqCoreObjects.menuBar_Item_File)
    time.sleep(2)
    print("Clicking Logout button")
    CommonActions.left_click_object(MosaiqCoreObjects.file_MenuItem_Logout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def confirm_successful_logout(waitTimeout: int = 30000) -> bool:
    """Confirms the user is returned to the login form after logout."""
    return CommonActions.wait_for_object_to_appear(MosaiqCoreObjects.dashboard_Username_TextBox, waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_exit_button() -> None:
    """Locates the Exit Button on the main dashboard > clicks located object using the primary mouse button.
    """
    print("Clicking Exit button")
    CommonActions.left_click_object(MosaiqCoreObjects.menuBar_Item_File)
    time.sleep(2)
    CommonActions.left_click_object(MosaiqCoreObjects.file_MenuItem_Exit)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def confirm_successful_exit(waitTimeout: int = 30000) -> bool:
    """Confirms the main MOSAIQ window has disappeared after exit."""
    return CommonActions.wait_for_object_to_disappear(MosaiqCoreObjects.mOSAIQ_Main_Window, waitTimeout)
